.stratsim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #1b2330;
    background: linear-gradient(165deg, #eef1f6 0%, #e4e9f1 100%);
    border-radius: 18px;
}

.stratsim-container * {
    box-sizing: border-box;
}

.stratsim-header {
    text-align: center;
    padding: 26px 20px 22px;
    background: linear-gradient(135deg, #0f1d33 0%, #1c2f4e 55%, #2a4368 100%);
    color: #f2f5fb;
    border-radius: 16px;
    margin-bottom: 20px;
    box-shadow: 0 10px 30px rgba(15, 29, 51, 0.32);
    border-bottom: 3px solid #c79a3a;
}

.stratsim-header h1 {
    margin: 8px 0 10px;
    font-size: 2.3rem;
    font-weight: 800;
    letter-spacing: -0.5px;
}

.stratsim-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #e7c879;
    background: rgba(199, 154, 58, 0.14);
    padding: 5px 14px;
    border-radius: 999px;
}

.stratsim-subtitle {
    margin: 0 auto;
    max-width: 800px;
    font-size: 1rem;
    line-height: 1.55;
    color: #d7deec;
}

.stratsim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #2a3b56;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.stratsim-period-counter #currentDay,
.stratsim-period-counter #maxPeriods {
    font-weight: 800;
    color: #0f1d33;
}

.stratsim-round-name {
    background: #d6deee;
    color: #1c2f4e;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.stratsim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #8a5a12;
    background: #f6ecd4;
    padding: 4px 12px;
    border-radius: 999px;
}

.stratsim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.stratsim-status-card {
    background: #ffffff;
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #d6dde9;
    box-shadow: 0 4px 14px rgba(15, 29, 51, 0.06);
    border-top: 4px solid #2a4368;
}

.stratsim-card-roic { border-top-color: #1f6f5c; }
.stratsim-card-growth { border-top-color: #2f6fb0; }
.stratsim-card-fit { border-top-color: #c79a3a; }
.stratsim-card-capital { border-top-color: #6a4fa0; }

.stratsim-label {
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #5d6b81;
}

.stratsim-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #0f1d33;
}

.stratsim-card-roic .stratsim-value { color: #1f6f5c; }
.stratsim-card-growth .stratsim-value { color: #2f6fb0; }
.stratsim-card-fit .stratsim-value { color: #b3851f; }
.stratsim-card-capital .stratsim-value { color: #6a4fa0; }

.stratsim-sublabel {
    font-size: 0.76rem;
    color: #6f7d92;
    line-height: 1.35;
}

.stratsim-roic-fail .stratsim-value { color: #c0392b; }
.stratsim-roic-target .stratsim-value { color: #1f6f5c; }
.stratsim-growth-fail .stratsim-value { color: #c0392b; }
.stratsim-growth-target .stratsim-value { color: #2f6fb0; }

.stratsim-capital-over { border-top-color: #c0392b; }
.stratsim-capital-over .stratsim-value { color: #c0392b; }

.stratsim-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #0f1d33;
    color: #eaeffa;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
    border-left: 4px solid #c79a3a;
}

.stratsim-budget-bar #budgetDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
    color: #e7c879;
}

.stratsim-briefing {
    display: flex;
    gap: 14px;
    background: #ffffff;
    border-left: 5px solid #2a4368;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 4px 14px rgba(15, 29, 51, 0.05);
}

.stratsim-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.stratsim-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #0f1d33;
    margin-bottom: 6px;
}

.stratsim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #36465e;
}

.stratsim-briefing-text strong { color: #1f6f5c; }
.stratsim-briefing-text em { color: #8a5a12; font-style: italic; }

.stratsim-controls {
    background: #ffffff;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #d6dde9;
    box-shadow: 0 4px 14px rgba(15, 29, 51, 0.06);
}

.stratsim-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #0f1d33;
    border-bottom: 2px solid #e4e9f1;
    padding-bottom: 8px;
}

.stratsim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #28344a;
    margin: 14px 0 6px;
}

.stratsim-container select,
.stratsim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #bcc8db;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #f7f9fc;
    color: #1b2330;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.stratsim-container select:focus,
.stratsim-container input[type="number"]:focus {
    outline: none;
    border-color: #2a4368;
    box-shadow: 0 0 0 3px rgba(42, 67, 104, 0.15);
}

.stratsim-container select option {
    background-color: #ffffff;
    color: #1b2330;
}

.stratsim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #c79a3a;
}

.stratsim-range-readout,
.stratsim-alloc-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #1c2f4e;
    margin-top: 4px;
}

.stratsim-range-readout span:last-child,
.stratsim-alloc-readout span:nth-child(2) {
    color: #1f6f5c;
    font-weight: 800;
}

.stratsim-hint {
    font-size: 0.8rem;
    color: #6f7d92;
    margin-top: 4px;
    line-height: 1.4;
}

.stratsim-alloc-grid {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin-top: 4px;
}

.stratsim-alloc-row {
    display: flex;
    align-items: center;
    gap: 12px;
    background: #f3f6fb;
    border: 1px solid #dde4ef;
    border-radius: 9px;
    padding: 8px 12px;
}

.stratsim-alloc-name {
    flex: 1;
    font-size: 0.88rem;
    font-weight: 600;
    color: #28344a;
}

.stratsim-alloc-row input[type="number"] {
    width: 90px;
    flex: 0 0 90px;
}

.stratsim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.stratsim-container .btn-primary {
    background: linear-gradient(135deg, #1c2f4e 0%, #2a4368 100%);
    border: none;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 6px 16px rgba(28, 47, 78, 0.30);
}

.stratsim-container .btn-primary:hover {
    filter: brightness(1.12);
}

.stratsim-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #bcc8db;
    color: #5d6b81;
}

.stratsim-coach {
    background: #0f1d33;
    color: #eaeffa;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(15, 29, 51, 0.24);
    border-left: 4px solid #c79a3a;
}

.stratsim-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #e7c879;
    margin-bottom: 8px;
}

.stratsim-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.stratsim-coach-body strong { color: #f1d690; }
.stratsim-coach-body em { color: #f3c39a; font-style: italic; }

.stratsim-history,
.stratsim-chart {
    background: #ffffff;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #d6dde9;
    box-shadow: 0 4px 14px rgba(15, 29, 51, 0.06);
}

.stratsim-history h3,
.stratsim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #0f1d33;
}

.stratsim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #28344a;
}

.stratsim-container table#usfHistoryTable th {
    background: #eaeef5;
    color: #0f1d33;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #d4dce9;
}

.stratsim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #eef2f7;
}

.stratsim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #f8fafd;
}

.stratsim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .stratsim-container {
        padding: 14px;
    }
    .stratsim-header h1 {
        font-size: 1.7rem;
    }
    .stratsim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .stratsim-value {
        font-size: 2rem;
    }
    .stratsim-clock {
        margin-left: 0;
    }
    .stratsim-period-counter {
        font-size: 0.88rem;
    }
    .stratsim-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .stratsim-alloc-row {
        flex-wrap: wrap;
    }
    .stratsim-alloc-row input[type="number"] {
        width: 100%;
        flex: 1 1 100%;
    }
    .stratsim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}

/* ── v1.1.0 completion debrief (formatCompletionMessage) — append-only, namespaced ── */
.st-cm { font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; color: #1a2740; background: linear-gradient(165deg, #eef1f6 0%, #e4e9f1 100%); border: 1px solid #d3dae6; border-radius: 16px; padding: 22px 24px; margin-top: 8px; }
.st-cm-incomplete { font-size: 1rem; color: #64748b; margin: 0; text-align: center; }
.st-cm-head { display: flex; flex-wrap: wrap; align-items: stretch; gap: 16px; margin-bottom: 18px; }
.st-cm-score { flex: 1 1 200px; background: linear-gradient(135deg, #0f1d33 0%, #1c2f4e 55%, #2a4368 100%); color: #f2f6fc; border-radius: 14px; padding: 18px 20px; box-shadow: 0 8px 22px rgba(15,29,51,0.28); }
.st-cm-score-num { font-size: 2.6rem; font-weight: 800; line-height: 1; letter-spacing: -1px; }
.st-cm-score-den { font-size: 1.05rem; font-weight: 600; opacity: 0.82; margin-left: 2px; }
.st-cm-score-lbl { margin-top: 6px; font-size: 0.82rem; text-transform: uppercase; letter-spacing: 0.8px; color: #a9c6e8; font-weight: 700; }
.st-cm-verdict { flex: 2 1 260px; background: #ffffff; border: 1px solid #d3dae6; border-left: 5px solid #1f6f5c; border-radius: 14px; padding: 18px 20px; display: flex; flex-direction: column; justify-content: center; }
.st-cm-verdict-lbl { font-size: 0.78rem; text-transform: uppercase; letter-spacing: 0.9px; color: #64748b; font-weight: 700; }
.st-cm-verdict-tier { font-size: 1.5rem; font-weight: 800; color: #0f1d33; margin-top: 4px; letter-spacing: -0.4px; }
.st-cm-section { margin-top: 16px; }
.st-cm-section-h { font-size: 0.82rem; text-transform: uppercase; letter-spacing: 0.9px; color: #2a4368; font-weight: 700; margin-bottom: 8px; }
.st-cm-chips { display: flex; flex-wrap: wrap; gap: 8px; }
.st-cm-chip { display: inline-flex; align-items: center; gap: 6px; font-size: 0.86rem; font-weight: 600; padding: 6px 12px; border-radius: 999px; border: 1px solid transparent; }
.st-cm-ok { background: #e4f1ec; color: #1f6f5c; border-color: #bfe0d3; }
.st-cm-no { background: #f8e6e3; color: #b23b3b; border-color: #eec7c1; }
.st-cm-ico { font-weight: 800; }
.st-cm-kpis { display: grid; grid-template-columns: repeat(4, 1fr); gap: 10px; }
.st-cm-kpi { background: #ffffff; border: 1px solid #d3dae6; border-top: 4px solid #2a4368; border-radius: 12px; padding: 12px 14px; text-align: center; }
.st-cm-kpi:nth-child(1) { border-top-color: #1f6f5c; }
.st-cm-kpi:nth-child(2) { border-top-color: #2f6fb0; }
.st-cm-kpi:nth-child(3) { border-top-color: #c79a3a; }
.st-cm-kpi:nth-child(4) { border-top-color: #6a4fa0; }
.st-cm-kpi-val { font-size: 1.5rem; font-weight: 800; color: #0f1d33; line-height: 1.1; }
.st-cm-kpi-lbl { font-size: 0.72rem; text-transform: uppercase; letter-spacing: 0.5px; color: #64748b; font-weight: 700; margin-top: 4px; }
.st-cm-kpi-sub { font-size: 0.7rem; color: #93a0b4; margin-top: 3px; }
.st-cm-insights { margin: 0; padding-left: 20px; }
.st-cm-insights li { font-size: 0.9rem; color: #33415a; line-height: 1.5; margin-bottom: 4px; }
@media (max-width: 640px) { .st-cm-kpis { grid-template-columns: repeat(2, 1fr); } .st-cm-head { flex-direction: column; } }

