(function() {
    'use strict';

    class StrategyAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Strategy in Action`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card.
            this.START_ROIC = 11.0;        // current ROIC
            this.TARGET_ROIC = 16.0;       // Year-3 mandate
            this.START_GROWTH = 2.0;       // trailing growth
            this.TARGET_GROWTH = 8.0;      // mandated growth p.a.
            this.CAPITAL_CAP = 48;         // €48M envelope (cut 20% from €60M)
            this.CAPITAL_DEMAND = 78;      // €78M of investment cases
            this.YEAR3_GAP = 95;           // ~€95M revenue gap to mandate
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    roic: this.START_ROIC,
                    growth: this.START_GROWTH,
                    fit: 20,
                    capitalUsed: 0,
                    overSpent: false,
                    hedged: false,
                    roicHistory: [this.START_ROIC],
                    growthHistory: [this.START_GROWTH],
                    fitHistory: [20],
                    coachMessages: [],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seed defaults to a MIDDLING / neutral mix — never the textbook-correct play.
                state.decisions = {
                    lever: `margin`,
                    segment: `equipment`,
                    root: `market`,
                    gap: 60,
                    direction: `volume`,
                    stop: `trim`,
                    conviction: 50,
                    kpi: `inflated`,
                    incentive: `addgrowth`,
                    cadence: `annual`,
                    style: `financial`,
                    serviceCapex: 10,
                    heatpumpCapex: 14,
                    automationCapex: 14,
                    kill: `vague`,
                    defence: `hedged`
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const lever = document.getElementById(`leverInput`);
                const seg = document.getElementById(`segmentInput`);
                const root = document.getElementById(`rootInput`);
                const gap = document.getElementById(`gapInput`);
                if (lever) decisions.lever = lever.value;
                if (seg) decisions.segment = seg.value;
                if (root) decisions.root = root.value;
                if (gap) decisions.gap = parseFloat(gap.value);
                if (!Number.isFinite(decisions.gap) || decisions.gap < 0 || decisions.gap > 200) {
                    warn(`warn_gap_range`); return false;
                }
            } else if (round === 2) {
                const dir = document.getElementById(`directionInput`);
                const stop = document.getElementById(`stopInput`);
                const cv = document.getElementById(`convictionInput`);
                if (dir) decisions.direction = dir.value;
                if (stop) decisions.stop = stop.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            } else if (round === 3) {
                const kpi = document.getElementById(`kpiInput`);
                const inc = document.getElementById(`incentiveInput`);
                const cad = document.getElementById(`cadenceInput`);
                const sty = document.getElementById(`styleInput`);
                if (kpi) decisions.kpi = kpi.value;
                if (inc) decisions.incentive = inc.value;
                if (cad) decisions.cadence = cad.value;
                if (sty) decisions.style = sty.value;
            } else if (round === 4) {
                const sc = document.getElementById(`serviceCapexInput`);
                const hp = document.getElementById(`heatpumpCapexInput`);
                const au = document.getElementById(`automationCapexInput`);
                const kill = document.getElementById(`killInput`);
                const def = document.getElementById(`defenceInput`);
                if (sc) decisions.serviceCapex = parseFloat(sc.value);
                if (hp) decisions.heatpumpCapex = parseFloat(hp.value);
                if (au) decisions.automationCapex = parseFloat(au.value);
                if (kill) decisions.kill = kill.value;
                if (def) decisions.defence = def.value;
                const parts = [decisions.serviceCapex, decisions.heatpumpCapex, decisions.automationCapex];
                if (parts.some((v) => !Number.isFinite(v) || v < 0)) {
                    warn(`warn_capex_negative`); return false;
                }
                const total = decisions.serviceCapex + decisions.heatpumpCapex + decisions.automationCapex;
                // The board will not reverse the cut: spending above €48M is a wish-list, blocked
                // unless the team explicitly chose the wish-list option (which is scored as an error).
                if (total > this.CAPITAL_CAP + 0.001 && decisions.kill !== `wishlist`) {
                    warn(`warn_capex_over`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            // Deltas this round. fit = strategy<->control<->capital coherence (the spine).
            // roic/growth move on fit-quality plus round-specific levers.
            let fitDelta = 0, roicDelta = 0, growthDelta = 0;
            let spend = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Diagnose: ROIC decomposition, segment ranking, root cause, gap sizing.
                // Correct lever = BOTH margin and capital turn (margin via mix-shift, turn via
                // releasing working capital / automation). Volume-only is the "manage for average" trap.
                if (d.lever === `both`) { fitDelta += 13; roicDelta += 0.2; coachKey = `coach_r1_lever_both`; }
                else if (d.lever === `margin`) { fitDelta += 4; }
                else if (d.lever === `capturn`) { fitDelta += 4; }
                else { fitDelta -= 9; roicDelta -= 0.3; coachKey = `coach_r1_lever_volume`; }

                // Highest growth-and-return potential = service & controls (margin, low capital intensity).
                if (d.segment === `service`) { fitDelta += 11; growthDelta += 0.2; }
                else if (d.segment === `equipment`) { fitDelta += 2; coachKey = (coachKey === `coach_default`) ? `coach_r1_seg_equipment` : coachKey; }
                else { fitDelta -= 7; coachKey = `coach_r1_seg_install`; }

                // Root cause: "managed for the average" — strategy as extrapolation, no real choice.
                if (d.root === `legacy`) { fitDelta += 11; coachKey = `coach_r1_root_legacy`; }
                else if (d.root === `market`) { fitDelta -= 7; coachKey = `coach_r1_root_market`; }
                else { fitDelta -= 5; coachKey = `coach_r1_root_capital`; }

                // Gap sizing: the Year-3 gap is ~€95M. Reward landing in a credible band.
                if (d.gap >= 80 && d.gap <= 110) { fitDelta += 5; }
                else if (d.gap < 50) { fitDelta -= 6; coachKey = `coach_r1_gap_low`; }

                summaryKey = (d.lever === `both` && d.segment === `service` && d.root === `legacy`) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Decide: commit to ONE coherent direction. Servitization fits the diagnosis best
                // (margin + low capital intensity → ROIC), but premium also wins if committed.
                // Hedging across all three = Common Error 2 (win at none).
                if (d.direction === `servitization`) { fitDelta += 13; roicDelta += 0.3; growthDelta += 0.6; coachKey = `coach_r2_servitization`; }
                else if (d.direction === `premium`) { fitDelta += 11; roicDelta += 0.25; growthDelta += 0.8; coachKey = `coach_r2_premium`; }
                else if (d.direction === `volume`) { fitDelta += 4; roicDelta -= 0.3; growthDelta += 0.7; coachKey = `coach_r2_volume`; }
                else { fitDelta -= 16; roicDelta -= 0.6; growthDelta -= 0.4; ds.hedged = true; coachKey = `coach_r2_hedge`; }

                // Naming what you STOP doing funds the bet and lifts capital turn.
                if (d.stop === `lowmargin`) { fitDelta += 7; roicDelta += 0.3; }
                else if (d.stop === `trim`) { fitDelta += 1; }
                else { fitDelta -= 9; coachKey = `coach_r2_stopnothing`; }

                // Conviction: commitment to a single bet (irrelevant if you hedged).
                if (d.direction !== `hedge`) {
                    if (d.conviction >= 70) { fitDelta += 5; growthDelta += 0.2; }
                    else if (d.conviction <= 30) { fitDelta -= 7; coachKey = `coach_r2_lowconviction`; }
                }

                summaryKey = (d.direction !== `hedge` && d.stop === `lowmargin` && d.conviction >= 60) ? `sum_r2_good` : `sum_r2_weak`;
            } else if (round === 3) {
                // Design: the planning & control system — the heart of Gibbons' thesis.
                // Focused KPI set the financial-control parent will use (not 12-metric inflation,
                // not so thin it has no strategy content).
                if (d.kpi === `focused`) { fitDelta += 11; coachKey = `coach_r3_kpi_focused`; }
                else if (d.kpi === `inflated`) { fitDelta -= 9; coachKey = `coach_r3_kpi_inflated`; }
                else { fitDelta -= 3; coachKey = `coach_r3_kpi_financial`; }

                // Incentive realignment is the single most instructive lever (Common Error 1).
                // Strategy-without-system: change the slide, not the pay → strategy never becomes behaviour.
                // This is the decisive round-3 lever: legacy incentives sink the whole plan.
                if (d.incentive === `realign`) { fitDelta += 14; roicDelta += 0.4; growthDelta += 0.6; coachKey = `coach_r3_realign`; }
                else if (d.incentive === `addgrowth`) { fitDelta -= 6; growthDelta += 0.1; coachKey = `coach_r3_addgrowth`; }
                else { fitDelta -= 20; roicDelta -= 1.2; growthDelta -= 1.0; coachKey = `coach_r3_legacy`; }

                // Cadence: a new strategy needs a rolling/milestone rhythm, not the legacy budget.
                if (d.cadence === `rolling`) { fitDelta += 7; }
                else { fitDelta -= 5; coachKey = (coachKey === `coach_default`) ? `coach_r3_annual` : coachKey; }

                // Control style fit: a financial-control parent will use strategic control, override
                // a 14-metric balanced scorecard, and reject co-owning deep operating detail.
                if (d.style === `strategic`) { fitDelta += 7; }
                else if (d.style === `planning`) { fitDelta -= 7; coachKey = `coach_r3_style_planning`; }
                else { fitDelta += 1; }

                summaryKey = (d.incentive === `realign` && d.kpi === `focused`) ? `sum_r3_good` : (d.incentive === `legacy` ? `sum_r3_nosystem` : `sum_r3_weak`);
            } else if (round === 4) {
                // Allocate & defend: capital pattern must MATCH the chosen strategy (strategic fit),
                // stay within €48M, and name what is killed. Reward coherence with the direction.
                const sc = d.serviceCapex, hp = d.heatpumpCapex, au = d.automationCapex;
                spend = sc + hp + au;

                // Concentration: a committed plan backs one or two cases heavily, not all three thinly.
                const maxCase = Math.max(sc, hp, au);
                const total = spend > 0 ? spend : 1;
                const concentration = maxCase / total;          // 0.33 = perfectly spread, →1 = focused
                const spread = sc > 4 && hp > 4 && au > 4;       // all three funded = hedged capital

                // Strategic fit: does the capital go where the Round-2 strategy went?
                let aligned = false;
                if (d.direction === `servitization`) aligned = (sc >= hp && sc >= au && sc >= 14);
                else if (d.direction === `volume`) aligned = (hp >= sc && hp >= 12);
                else if (d.direction === `premium`) aligned = ((sc + au) >= hp && au >= 6);
                else aligned = false; // hedged direction has nothing to be consistent with

                if (aligned && !spread) { fitDelta += 15; roicDelta += 0.5; growthDelta += 0.7; coachKey = `coach_r4_aligned`; }
                else if (aligned) { fitDelta += 5; roicDelta += 0.2; growthDelta += 0.3; }
                else if (spread || concentration < 0.45) { fitDelta -= 14; roicDelta -= 0.8; ds.hedged = true; coachKey = `coach_r4_spread`; }
                else { fitDelta -= 10; roicDelta -= 0.6; coachKey = `coach_r4_misaligned`; }

                // Automation always helps capital turn / ROIC a little (supports any archetype).
                if (au >= 8) roicDelta += 0.2;

                // Killing/deferring explicitly vs ignoring the cut (Common Error 3).
                if (d.kill === `named`) { fitDelta += 7; }
                else if (d.kill === `vague`) { fitDelta -= 5; }
                else { // wishlist: funded €78M as if the cut never happened — penalise hard.
                    fitDelta -= 20; roicDelta -= 1.4; coachKey = `coach_r4_wishlist`;
                }

                // Board defence: words vs numbers.
                if (d.defence === `consistent`) { fitDelta += 7; roicDelta += 0.2; coachKey = (aligned && d.kill === `named`) ? `coach_r4_boardready` : coachKey; }
                else if (d.defence === `hedged`) { fitDelta -= 8; ds.hedged = true; coachKey = (coachKey === `coach_default`) ? `coach_r4_defhedged` : coachKey; }
                else { fitDelta -= 12; roicDelta -= 0.4; coachKey = `coach_r4_words`; }

                summaryKey = (aligned && !spread && d.kill === `named` && d.defence === `consistent`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // Resource accounting (capital is cumulative across the plan; committed mainly in R4).
            ds.capitalUsed = Math.round((ds.capitalUsed + spend) * 10) / 10;
            if (ds.capitalUsed > this.CAPITAL_CAP + 0.001) ds.overSpent = true;

            // Strategic Fit moves on a scaled delta so meters stay low with headroom early — every
            // wrong choice keeps registering through the final round rather than pegging a meter.
            const FIT_SCALE = 0.55;
            const scaledFit = fitDelta * FIT_SCALE;
            ds.fit = Math.max(0, Math.min(100, ds.fit + scaledFit));

            // ROIC & growth move on the round-lever nudges PLUS a coherence term proportional to the
            // fit built (or lost) this round — so only a consistent plan compounds toward the mandate,
            // while strategy-without-system / hedging / wish-listing actively erode the ratio. The
            // coherence term carries the sign of fitDelta so a bad round drags ROIC down, not just flat.
            // Multipliers are tuned so the best play lands ~ROIC 17 / Fit 90 (below the caps) and the
            // weakest play stalls near ~ROIC 11–12 (above the floor) — no saturation either end.
            const coherence = scaledFit >= 0 ? scaledFit * 0.058 : scaledFit * 0.085;
            ds.roic = Math.max(8.5, Math.min(18.5, ds.roic + roicDelta + coherence));
            ds.growth = Math.max(0, Math.min(11, ds.growth + growthDelta + coherence * 1.05));

            ds.roicHistory.push(Math.round(ds.roic * 10) / 10);
            ds.growthHistory.push(Math.round(ds.growth * 10) / 10);
            ds.fitHistory.push(Math.round(ds.fit));

            // v1.1.0 fix — persist composite where Express grading/reporting reads it
            // (results_utils.php express_resolveDomainScore -> performance.overallScore, then top-level score).
            const composite = this._composite(ds);
            if (!ds.performance || typeof ds.performance !== `object`) ds.performance = {};
            ds.performance.overallScore = composite;
            ds.score = composite;

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            ds.coachMessages.push(coachMsg);
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            return {
                period: state.currentPeriod,
                roic: Math.round(ds.roic * 10) / 10,
                roicDelta: Math.round((roicDelta + coherence) * 10) / 10,
                growth: Math.round(ds.growth * 10) / 10,
                growthDelta: Math.round((growthDelta + coherence * 1.05) * 10) / 10,
                fit: Math.round(ds.fit),
                fitDelta: Math.round(fitDelta),
                capitalUsed: ds.capitalUsed,
                hedged: ds.hedged,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg,
                score: composite,
                overallScore: composite
            };
        }

        _money(valM) {
            // Locale-aware EUR in €M. EN: "€48M" (symbol before). ES: "48 M€" (symbol after, comma decimal).
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            const n = Math.round(Number(valM) * 10) / 10;
            const hasDec = Math.abs(n - Math.round(n)) > 0.001;
            if (lang === `es`) {
                const s = hasDec ? n.toFixed(1).replace(`.`, `,`) : String(Math.round(n));
                return s + ` M€`;
            }
            const s = hasDec ? n.toFixed(1) : String(Math.round(n));
            return `€` + s + `M`;
        }

        setupUI(uiManager) {
            const self = this;
            uiManager.bind(`currentDay`, `currentPeriod`);
            uiManager.bind(`maxPeriods`, `maxPeriods`);

            uiManager.bind(`roicDisplay`, `domainState.roic`, (v) => {
                const card = document.querySelector(`.stratsim-card-roic`);
                if (card) {
                    card.classList.toggle(`stratsim-roic-target`, Number(v) >= self.TARGET_ROIC - 0.001);
                    card.classList.toggle(`stratsim-roic-fail`, Number(v) < self.TARGET_ROIC - 0.001);
                }
                return (Math.round(Number(v) * 10) / 10).toFixed(1) + `%`;
            });
            uiManager.bind(`growthDisplay`, `domainState.growth`, (v) => {
                const card = document.querySelector(`.stratsim-card-growth`);
                if (card) {
                    card.classList.toggle(`stratsim-growth-target`, Number(v) >= self.TARGET_GROWTH - 0.001);
                    card.classList.toggle(`stratsim-growth-fail`, Number(v) < self.TARGET_GROWTH - 0.001);
                }
                return (Math.round(Number(v) * 10) / 10).toFixed(1) + `%`;
            });
            uiManager.bind(`fitDisplay`, `domainState.fit`, (v) => Math.round(v));
            uiManager.bind(`capitalDisplay`, `domainState.capitalUsed`, (v) => {
                const card = document.querySelector(`.stratsim-card-capital`);
                if (card) card.classList.toggle(`stratsim-capital-over`, Number(v) > self.CAPITAL_CAP + 0.001);
                return self._money(v) + ` / ` + self._money(self.CAPITAL_CAP);
            });
            uiManager.bind(`budgetDisplay`, `domainState.capitalUsed`, (v) => self._money(v) + ` / ` + self._money(self.CAPITAL_CAP));

            // Conviction slider readout.
            const cv = document.getElementById(`convictionInput`);
            const cvReadout = document.getElementById(`convictionReadout`);
            if (cv && cvReadout) {
                cvReadout.textContent = cv.value;
                cv.addEventListener(`input`, function() { cvReadout.textContent = cv.value; });
            }

            // Capital-allocation live total.
            const capIds = [`serviceCapexInput`, `heatpumpCapexInput`, `automationCapexInput`];
            const allocReadout = document.getElementById(`allocReadout`);
            const recompute = function() {
                let total = 0;
                capIds.forEach((id) => {
                    const el = document.getElementById(id);
                    if (el) total += (parseFloat(el.value) || 0);
                });
                total = Math.round(total * 10) / 10;
                if (allocReadout) allocReadout.textContent = self._money(total);
                const bar = document.querySelector(`.stratsim-alloc-readout`);
                if (bar) bar.style.color = (total > self.CAPITAL_CAP + 0.001) ? `#c0392b` : ``;
            };
            capIds.forEach((id) => {
                const el = document.getElementById(id);
                if (el) el.addEventListener(`input`, recompute);
            });
            recompute();
        }

