        getChartData(state) {
            const ds = state.domainState;
            const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;
            const labels = ds.roicHistory.map((_, i) => (i === 0 ? t(`chart_start`) : `R` + i));
            return {
                stratChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.roicHistory },
                        { data: ds.growthHistory },
                        { data: ds.fitHistory }
                    ]
                }
            };
        }

        _composite(ds) {
            // Verbatim v1.0.0 composite (was inline in getPerformanceSummary), extracted so the
            // per-period persisted score and the completion summary are identical by construction.
            const roic = Math.round(ds.roic * 10) / 10;
            const growth = Math.round(ds.growth * 10) / 10;
            const fit = Math.round(ds.fit);
            const roicScore = Math.min(100, (roic / this.TARGET_ROIC) * 100);
            const growthScore = Math.min(100, (growth / this.TARGET_GROWTH) * 100);
            return Math.round(roicScore * 0.35 + growthScore * 0.30 + fit * 0.35);
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const roic = Math.round(ds.roic * 10) / 10;
            const growth = Math.round(ds.growth * 10) / 10;
            const fit = Math.round(ds.fit);

            const hitRoic = roic >= this.TARGET_ROIC - 0.001;
            const hitGrowth = growth >= this.TARGET_GROWTH - 0.001;
            const hitMandate = hitRoic && hitGrowth;
            const coherent = fit >= 60;
            // Composite on 0–100: ROIC and growth scaled against their mandates, plus fit.
            const roicScore = Math.min(100, (roic / this.TARGET_ROIC) * 100);
            const growthScore = Math.min(100, (growth / this.TARGET_GROWTH) * 100);
            const composite = this._composite(ds);

            // v1.1.0 fix — tier labels were hardcoded English; now i18n-keyed (localized es).
            let tierKey = `grade_divest`;
            if (hitMandate && coherent && composite >= 80) tierKey = `grade_closed`;
            else if (hitMandate && coherent) tierKey = `grade_credible`;
            else if (hitMandate && ds.hedged) tierKey = `grade_incoherent`;
            else if (hitMandate) tierKey = `grade_thin`;
            else if (roic >= 13.5 || growth >= 5.5) tierKey = `grade_closing`;
            const performance = window.mySimulation.t(tierKey);

            const insights = [];
            if (hitMandate && coherent) insights.push(window.mySimulation.t(`insight_closed`));
            else if (hitMandate && ds.hedged) insights.push(window.mySimulation.t(`insight_incoherent`));
            else if (hitMandate) insights.push(window.mySimulation.t(`insight_thin`));
            else insights.push(window.mySimulation.t(`insight_short`));

            if (ds.hedged) insights.push(window.mySimulation.t(`insight_hedged`));
            if (ds.overSpent) insights.push(window.mySimulation.t(`insight_overspent`));
            if (fit < 45) insights.push(window.mySimulation.t(`insight_lowfit`));
            if (hitMandate && coherent && fit >= 75) insights.push(window.mySimulation.t(`insight_embedded`));

            return {
                roic: roic,
                growth: growth,
                fit: fit,
                hitRoic: hitRoic,
                hitGrowth: hitGrowth,
                hitMandate: hitMandate,
                composite: composite,
                performance: performance,
                performanceKey: tierKey,
                capitalUsed: ds.capitalUsed,
                onBudget: ds.capitalUsed <= this.CAPITAL_CAP,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            const t = (k) => window.mySimulation.t(k);
            if (!summary || summary.composite == null) {
                return `<div class="st-cm"><p class="st-cm-incomplete">` + t(`cm_incomplete`) + `</p></div>`;
            }
            const s = summary;
            const chip = (ok, label) => `<span class="st-cm-chip ` + (ok ? `st-cm-ok` : `st-cm-no`) + `">` +
                `<span class="st-cm-ico">` + (ok ? `\u2713` : `\u2715`) + `</span>` + label + ` \u00b7 ` +
                (ok ? t(`cm_met`) : t(`cm_missed`)) + `</span>`;
            const kpi = (label, val, sub) => `<div class="st-cm-kpi"><div class="st-cm-kpi-val">` + val +
                `</div><div class="st-cm-kpi-lbl">` + label + `</div>` +
                (sub ? `<div class="st-cm-kpi-sub">` + sub + `</div>` : ``) + `</div>`;
            const cohOk = s.fit >= 60, budOk = !!s.onBudget;
            const insights = (s.insights || []).map((x) => `<li>` + x + `</li>`).join(``);
            return `` +
`<div class="st-cm">` +
  `<div class="st-cm-head">` +
    `<div class="st-cm-score"><div class="st-cm-score-num">` + Math.round(s.composite) +
       `<span class="st-cm-score-den">/100</span></div>` +
       `<div class="st-cm-score-lbl">` + t(`cm_score`) + `</div></div>` +
    `<div class="st-cm-verdict"><div class="st-cm-verdict-lbl">` + t(`cm_verdict`) + `</div>` +
       `<div class="st-cm-verdict-tier">` + s.performance + `</div></div>` +
  `</div>` +
  `<div class="st-cm-section"><div class="st-cm-section-h">` + t(`cm_targets`) + `</div>` +
    `<div class="st-cm-chips">` + chip(s.hitRoic, t(`cm_t_roic`)) + chip(s.hitGrowth, t(`cm_t_growth`)) +
      chip(cohOk, t(`cm_t_fit`)) + chip(budOk, t(`cm_t_capital`)) + `</div></div>` +
  `<div class="st-cm-section"><div class="st-cm-section-h">` + t(`cm_kpis`) + `</div>` +
    `<div class="st-cm-kpis">` +
      kpi(t(`roic_label`), (Math.round(s.roic * 10) / 10).toFixed(1) + `%`, t(`cm_sub_roic`)) +
      kpi(t(`growth_label`), (Math.round(s.growth * 10) / 10).toFixed(1) + `%`, t(`cm_sub_growth`)) +
      kpi(t(`fit_label`), Math.round(s.fit), t(`cm_sub_fit`)) +
      kpi(t(`capital_label`), `€` + (Math.round(s.capitalUsed)) + `M`, t(`cm_sub_capital`)) +
    `</div></div>` +
  (insights ? `<div class="st-cm-section"><div class="st-cm-section-h">` + t(`cm_insights`) +
      `</div><ul class="st-cm-insights">` + insights + `</ul></div>` : ``) +
`</div>`;
