        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.hedged && state.currentPeriod >= 2) return window.mySimulation.t(`hint_hedged`);
            if (ds.overSpent) return window.mySimulation.t(`hint_overspent`);
            if (ds.fit < 35) return window.mySimulation.t(`hint_fit`);
            if (state.currentPeriod >= 3 && ds.roic < 13) return window.mySimulation.t(`hint_behind`);
            if (ds.roic >= this.TARGET_ROIC - 0.001 && ds.growth >= this.TARGET_GROWTH - 0.001 && ds.fit >= 60) return window.mySimulation.t(`hint_strong`);
            return null;
        }

